(window.FREE_Q = window.FREE_Q || {})["ssc-mts"] = {"qs": [["General Awareness", "The Tropic of Cancer does NOT pass through which of the following states?", ["Bihar", "Jharkhand", "Chhattisgarh", "Tripura"], 0, "The Tropic of Cancer crosses eight states: Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura and Mizoram. Bihar lies entirely north of it."], ["English Language", "Fill in the blank with the most appropriate verb.\nNeither the teacher nor the students ______ present at the meeting yesterday.", ["was", "is", "were", "has been"], 2, "With 'neither … nor', the verb agrees with the nearer subject. 'Students' is plural and the time is past, so 'were' is correct."], ["English Language", "Which word is opposite in meaning to TRANSPARENT in: 'The bottle is made of transparent glass.'", ["Clear", "Opaque", "Bright", "Glossy"], 1, "Transparent means letting light pass through. Opaque means not letting light pass, so it is the antonym. 'Clear' is close to a synonym."], ["English Language", "Fill in the blank with the most appropriate word.\nHe has been living in Pune ______ 2018.", ["for", "from", "since", "by"], 2, "With the present perfect continuous, 'since' is used for a point of time (2018) and 'for' for a period of time (five years)."], ["Numerical Ability", "Find the value of (0.25 × 0.4) ÷ 0.05.", ["2", "0.2", "20", "0.5"], 0, "0.25 × 0.4 = 0.1. Then 0.1 ÷ 0.05 = 10 ÷ 5 = 2. Shifting the decimal points equally in numerator and denominator avoids errors."], ["Numerical Ability", "15 men can complete a piece of work in 24 days. How many men are needed to complete the same work in 18 days?", ["18", "22", "25", "20"], 3, "Total work = 15 × 24 = 360 man-days. Men required for 18 days = 360 ÷ 18 = 20. More men are needed because fewer days are available (inverse proportion)."], ["Reasoning Ability", "If 1 January 2025 was a Wednesday, what day of the week was 1 January 2026?", ["Wednesday", "Friday", "Thursday", "Tuesday"], 2, "2025 is not a leap year, so it has 365 days = 52 weeks + 1 odd day. The same date next year moves one day forward, from Wednesday to Thursday."], ["Numerical Ability", "If A : B = 2 : 3 and B : C = 4 : 5, then what is A : B : C?", ["8 : 12 : 15", "2 : 3 : 5", "8 : 12 : 16", "6 : 9 : 10"], 0, "Make B common: multiply the first ratio by 4 (8 : 12) and the second by 3 (12 : 15). So A : B : C = 8 : 12 : 15."], ["Reasoning Ability", "A man walks 6 km towards North, turns right and walks 8 km, then turns right again and walks 6 km. How far and in which direction is he from his starting point?", ["8 km East", "8 km West", "10 km North-East", "14 km East"], 0, "North 6 km, then East 8 km, then South 6 km. The north and south movements cancel out, leaving him 8 km due East of the starting point."], ["English Language", "Which of the following words has the correct spelling?", ["Neccessary", "Necessary", "Necesary", "Neccesary"], 1, "The correct spelling is 'necessary' — one 'c' and double 's'. A common memory aid: one collar, two sleeves."], ["General Awareness", "How many players of each team are on the court at a time in a standard game of kabaddi?", ["5", "9", "7", "11"], 2, "A kabaddi team fields seven players on court, with a few substitutes. Eleven is the number for cricket, hockey and football teams."], ["Numerical Ability", "What is the smallest number that must be added to 1000 so that the sum is exactly divisible by 23?", ["12", "11", "13", "9"], 0, "1000 ÷ 23 leaves remainder 11 (23 × 43 = 989). Adding 23 − 11 = 12 gives 1012 = 23 × 44. Choosing 11 confuses the remainder with the amount to be added."], ["Reasoning Ability", "What is the angle between the hour hand and the minute hand of a clock at 3:40?", ["130°", "120°", "140°", "150°"], 0, "Angle = |30H − 5.5M| = |90 − 220| = 130°. The hour hand moves 0.5° per minute, so it is not exactly on 3; ignoring this gives 150°."], ["Numerical Ability", "The price of sugar rises by 25%. By what percentage must a family reduce its consumption so that its expenditure on sugar remains unchanged?", ["25%", "15%", "22%", "20%"], 3, "Reduction = 25/(100 + 25) × 100 = 20%. Check: 1.25 × 0.80 = 1, so spending stays the same. Reducing by 25% would actually cut expenditure."], ["Reasoning Ability", "Find the next term of the series.\n3, 7, 15, 31, 63, ?", ["125", "126", "129", "127"], 3, "Each term is double the previous term plus 1: 3×2+1 = 7, 7×2+1 = 15, and so on. So 63 × 2 + 1 = 127."], ["General Awareness", "The Fundamental Duties of citizens were added to the Indian Constitution by which Constitutional Amendment?", ["44th Amendment, 1978", "52nd Amendment, 1985", "42nd Amendment, 1976", "73rd Amendment, 1992"], 2, "The 42nd Amendment (1976), based on the Swaran Singh Committee's recommendations, inserted Part IV-A (Article 51A) listing Fundamental Duties. The 44th Amendment removed property from the Fundamental Rights."], ["General Awareness", "Which gas makes up the largest share of the Earth's atmosphere by volume?", ["Nitrogen", "Oxygen", "Carbon dioxide", "Argon"], 0, "Nitrogen forms about 78% of dry air, oxygen about 21% and argon nearly 0.9%. Carbon dioxide is only a small fraction despite its importance for climate."], ["General Awareness", "Which Harappan site is known for a dockyard, suggesting maritime trade?", ["Mohenjo-daro", "Kalibangan", "Lothal", "Rakhigarhi"], 2, "Lothal in Gujarat had a brick-lined dockyard linked to trade routes. Mohenjo-daro is famous for the Great Bath and Kalibangan for ploughed fields."], ["English Language", "Fill in the blank with the most appropriate phrasal verb.\nThe doctor advised him to ______ smoking.", ["give up", "give in", "give off", "give away"], 0, "'Give up' means to stop doing something. 'Give in' means to surrender, 'give off' means to emit (smell or heat) and 'give away' means to donate or reveal."], ["Numerical Ability", "What is the area of a circle of radius 14 cm? (Take π = 22/7)", ["616 cm²", "88 cm²", "308 cm²", "1232 cm²"], 0, "Area = πr² = 22/7 × 14 × 14 = 616 cm². 88 cm is the circumference (2πr), a frequent mix-up between the two formulas."], ["Numerical Ability", "A train 240 m long runs at 72 km/h. How long will it take to cross a platform 160 m long?", ["12 seconds", "18 seconds", "20 seconds", "24 seconds"], 2, "72 km/h = 72 × 5/18 = 20 m/s. To cross a platform the train covers its own length plus the platform length: 240 + 160 = 400 m. Time = 400 ÷ 20 = 20 seconds."], ["Numerical Ability", "What is 12.5% of 640?", ["64", "80", "72", "96"], 1, "12.5% equals the fraction 1/8, so 12.5% of 640 = 640 ÷ 8 = 80. Remembering common fraction equivalents of percentages saves time in the exam."], ["Numerical Ability", "What is the compound interest on ₹8,000 at 10% per annum for 2 years, compounded annually?", ["₹1,680", "₹1,600", "₹1,760", "₹1,648"], 0, "Amount = 8000 × (1.1)² = ₹9,680, so CI = 9,680 − 8,000 = ₹1,680. Simple interest would be only ₹1,600; the extra ₹80 is interest on the first year's interest."], ["Reasoning Ability", "If 2 ★ 3 = 13 and 4 ★ 1 = 17, then what is the value of 5 ★ 2?", ["27", "10", "29", "25"], 2, "The rule is a ★ b = a² + b²: 4 + 9 = 13 and 16 + 1 = 17. Hence 5 ★ 2 = 25 + 4 = 29."], ["Numerical Ability", "A boat's speed in still water is 15 km/h and the speed of the stream is 3 km/h. How long will the boat take to go 36 km downstream and come back the same distance?", ["4.8 hours", "5 hours", "5.5 hours", "4 hours"], 1, "Downstream speed = 18 km/h, so 36 km takes 2 hours. Upstream speed = 12 km/h, so 36 km takes 3 hours. Total time = 2 + 3 = 5 hours."], ["Reasoning Ability", "Find the next letter of the series.\nB, E, H, K, ?", ["M", "O", "N", "L"], 2, "The letters move forward three places each time: B(2), E(5), H(8), K(11). The next is position 14, which is N."], ["English Language", "Identify the segment that contains a grammatical error.\nEach of the students / have submitted / the project on time.", ["Each of the students", "the project on time", "No error", "have submitted"], 3, "'Each of' takes a singular verb, so it should be 'has submitted'. The subject is 'each', not 'students'."], ["Numerical Ability", "The average of five numbers is 42. When one number is removed, the average of the remaining four becomes 40. What is the number removed?", ["48", "50", "52", "46"], 1, "Sum of five numbers = 5 × 42 = 210. Sum of the remaining four = 4 × 40 = 160. The removed number = 210 − 160 = 50."], ["English Language", "Read the passage and answer the question.\nRainwater harvesting means collecting rain from rooftops and storing it in tanks or letting it soak into the ground. In many towns, groundwater levels have fallen because more water is pumped out than is replaced. Harvesting rain helps refill underground water and reduces flooding of streets during heavy showers.\nAccording to the passage, why have groundwater levels fallen in many towns?", ["Rain has stopped falling in towns", "More water is pumped out than is replaced", "Rooftops absorb most of the rain", "Streets are flooded during heavy showers every year"], 1, "The passage clearly says groundwater has fallen 'because more water is pumped out than is replaced'. Flooding is mentioned only as a problem harvesting helps reduce."], ["Reasoning Ability", "Select the word that completes the analogy.\nBird : Nest :: Bee : ?", ["Den", "Burrow", "Stable", "Hive"], 3, "A bird lives in a nest; a bee lives in a hive. A den is a lion's or fox's home, a burrow a rabbit's and a stable a horse's."], ["General Awareness", "Which is the longest river of peninsular India?", ["Krishna", "Narmada", "Kaveri", "Godavari"], 3, "The Godavari, rising at Trimbakeshwar in Maharashtra and flowing into the Bay of Bengal, is the longest peninsular river and is often called the 'Dakshin Ganga'."], ["General Awareness", "Who presides over a joint sitting of both Houses of the Indian Parliament?", ["Vice-President of India", "Speaker of the Lok Sabha", "President of India", "Chairman of the Finance Commission"], 1, "Under Article 108 the President summons a joint sitting, but it is presided over by the Speaker of the Lok Sabha. The Vice-President chairs only the Rajya Sabha."], ["English Language", "Select the correct passive form of: The police have arrested the thief.", ["The thief has been arrested by the police.", "The thief was arrested by the police.", "The thief had been arrested by the police.", "The thief is being arrested by the police."], 0, "Present perfect active ('have arrested') becomes present perfect passive: has/have been + past participle. The singular subject 'thief' takes 'has been arrested'."], ["English Language", "Pick the word opposite in meaning to HUMBLE in: 'Despite his success, he remained humble.'", ["Modest", "Arrogant", "Polite", "Simple"], 1, "Humble means modest and not proud. Arrogant means having an exaggerated sense of one's importance, so it is the antonym. 'Modest' is a synonym."], ["English Language", "Select the most appropriate meaning of the idiom 'to break the ice'.", ["To start a conversation in an uneasy situation", "To end a long friendship", "To act very rudely", "To solve a difficult problem quickly and without any help"], 0, "'To break the ice' means to say or do something that relieves tension and gets people talking, for example at the start of a meeting with strangers."], ["Numerical Ability", "A shopkeeper marks his goods 40% above the cost price and then allows a discount of 15% on the marked price. What is his profit percentage?", ["25%", "21%", "19%", "15%"], 2, "Take CP = ₹100. Marked price = ₹140. After a 15% discount, SP = 140 × 0.85 = ₹119. Profit = ₹19 on ₹100, i.e. 19%. Subtracting 15 from 40 to get 25% is the common trap."], ["English Language", "Select the most appropriate improvement for the underlined part.\n'If I was you', I would accept the offer.", ["If I were you", "If I am you", "If I had been you", "No improvement"], 0, "Imaginary or hypothetical conditions use the subjunctive 'were' for all subjects: 'If I were you, I would…'. Hence 'was' must be replaced."], ["Reasoning Ability", "If P > Q, Q ≥ R and R > S, which of the following is definitely true?", ["Q = S", "P > S", "R > P", "S ≥ Q"], 1, "Combining the statements gives P > Q ≥ R > S, so P > S is always true. Q is greater than S, so Q = S and S ≥ Q are false, and R > P is impossible."], ["Numerical Ability", "A sum of money doubles itself in 8 years at simple interest. What is the rate of interest per annum?", ["8%", "10%", "12%", "12.5%"], 3, "If the sum doubles, interest equals the principal. So P × R × 8 / 100 = P, giving R = 100/8 = 12.5% per annum."], ["General Awareness", "The Battle of Plassey, which helped establish British power in Bengal, was fought in which year?", ["1757", "1764", "1761", "1857"], 0, "Robert Clive defeated Siraj-ud-Daulah at Plassey in 1757. The Battle of Buxar followed in 1764, and 1761 is the Third Battle of Panipat."], ["Reasoning Ability", "How many times does the digit 7 appear when all the numbers from 1 to 100 are written?", ["10", "20", "11", "19"], 1, "7 appears in the units place 10 times (7, 17 … 97) and in the tens place 10 times (70–79). 77 counts twice, giving 20 in total."], ["English Language", "Select the correct indirect form of: She said to me, \"Please help me.\"", ["She said to me that please help me.", "She requested me to help me.", "She told me that I should please help her.", "She requested me to help her."], 3, "A request in direct speech becomes 'requested + object + to-infinitive', and 'please' is dropped. The pronoun 'me' changes to 'her' to refer to the speaker."], ["General Awareness", "Kathakali, a classical dance form known for elaborate make-up and costumes, belongs to which state?", ["Tamil Nadu", "Odisha", "Manipur", "Kerala"], 3, "Kathakali comes from Kerala. Bharatanatyam is from Tamil Nadu, Odissi from Odisha and Manipuri from Manipur."], ["Reasoning Ability", "Pointing to a boy, Meena says, \"He is the son of the only son of my father's father.\" How is the boy related to Meena?", ["Cousin", "Father", "Nephew", "Brother"], 3, "The only son of Meena's paternal grandfather must be Meena's own father. The son of her father is her brother. Cousin would apply only if the grandfather had another son."], ["General Awareness", "In banking terminology, the 'repo rate' is the rate at which:", ["commercial banks lend to their most creditworthy customers", "RBI borrows money from commercial banks", "RBI lends short-term funds to commercial banks", "banks pay interest on savings deposits"], 2, "Under a repo, banks borrow from the Reserve Bank of India by selling securities with an agreement to repurchase them. RBI borrowing from banks is the reverse repo concept."], ["Reasoning Ability", "In a certain code language, FRIEND is written as HUMJTK. How will CANDLE be written in that language?", ["EDRJRL", "ECRIRL", "EDQIRL", "EDRIRL"], 3, "The letters are shifted forward by 2, 3, 4, 5, 6 and 7 places in order (F→H, R→U, I→M …). Applying the same shifts to CANDLE gives E, D, R, I, R, L = EDRIRL."], ["English Language", "Choose the word closest in meaning to ABUNDANT as used in: 'The region has abundant rainfall.'", ["Scarce", "Tiny", "Plentiful", "Hidden"], 2, "Abundant means existing in large quantities, so 'plentiful' is the synonym. 'Scarce' is its opposite, while 'tiny' and 'hidden' are unrelated."], ["General Awareness", "In which part of a plant cell does photosynthesis take place?", ["Mitochondria", "Ribosome", "Golgi apparatus", "Chloroplast"], 3, "Chloroplasts contain chlorophyll, which traps sunlight to make food. Mitochondria release energy through respiration and are called the powerhouse of the cell."], ["General Awareness", "Which Article of the Indian Constitution guarantees protection of life and personal liberty?", ["Article 14", "Article 21", "Article 19", "Article 32"], 1, "Article 21 states that no person shall be deprived of life or personal liberty except by procedure established by law. Article 14 deals with equality and Article 32 with constitutional remedies."], ["Reasoning Ability", "Five friends A, B, C, D and E sit in a row facing North. C sits in the middle. A sits to the immediate right of C. B sits at one of the extreme ends. D does not sit at an extreme end. E sits to the immediate right of A. Who sits at the extreme left end?", ["D", "B", "E", "A"], 1, "C is 3rd and A is 4th, so E is 5th (extreme right). B must take the other end, the 1st place, and D sits 2nd. Hence B is at the extreme left."], ["Numerical Ability", "Pipe A can fill a tank in 12 hours and pipe B can fill it in 18 hours. If both are opened together, in how much time will the tank be filled?", ["7 hours 30 minutes", "6 hours", "7 hours 12 minutes", "15 hours"], 2, "In one hour the pipes fill 1/12 + 1/18 = 5/36 of the tank. Time = 36/5 = 7.2 hours, which is 7 hours and 0.2 × 60 = 12 minutes."], ["General Awareness", "Scurvy is caused by the deficiency of which vitamin?", ["Vitamin A", "Vitamin D", "Vitamin K", "Vitamin C"], 3, "Vitamin C (ascorbic acid) is needed for collagen formation; its lack causes bleeding gums and scurvy. Vitamin D deficiency causes rickets and Vitamin A deficiency night blindness."], ["General Awareness", "What is the SI unit of electric current?", ["Volt", "Ohm", "Watt", "Ampere"], 3, "Electric current is measured in amperes, one of the seven SI base units. The volt measures potential difference, the ohm resistance and the watt power."], ["Reasoning Ability", "Statements:\nSome cats are dogs.\nNo dog is a rat.\nConclusions:\nI. Some cats are not rats.\nII. No cat is a rat.", ["Only conclusion II follows", "Both I and II follow", "Only conclusion I follows", "Neither I nor II follows"], 2, "The cats that are dogs cannot be rats, so some cats are definitely not rats (I follows). Other cats may or may not be rats, so II is not certain."], ["Numerical Ability", "What is the LCM of 18, 24 and 30?", ["360", "180", "720", "120"], 0, "18 = 2 × 3², 24 = 2³ × 3 and 30 = 2 × 3 × 5. Taking the highest power of each prime gives 2³ × 3² × 5 = 360. 180 is not divisible by 24."], ["Reasoning Ability", "Select the number that does not belong to the group.\n27, 64, 125, 150", ["27", "150", "64", "125"], 1, "27 = 3³, 64 = 4³ and 125 = 5³ are perfect cubes. 150 is not a perfect cube, so it is the odd one out."], ["English Language", "Read the passage and answer the question.\nThe village library opened with just two shelves of donated books. Within a year, children were coming every evening, and their parents began borrowing newspapers. The librarian, a retired teacher, also started a weekly reading hour for those who could not read well.\nWhich word best describes the overall tone of the passage?", ["Critical", "Encouraging", "Sorrowful", "Sarcastic"], 1, "The passage describes a small library that grows and helps children and adults, so its tone is positive and encouraging. Nothing in it criticises, mourns or mocks anyone."], ["General Awareness", "Who founded the Arya Samaj in 1875?", ["Raja Ram Mohan Roy", "Swami Dayananda Saraswati", "Swami Vivekananda", "Ishwar Chandra Vidyasagar"], 1, "Swami Dayananda Saraswati founded the Arya Samaj in Bombay in 1875 with the call 'Go back to the Vedas'. Raja Ram Mohan Roy founded the Brahmo Samaj."], ["Reasoning Ability", "In a row of 40 children, Anu is 12th from the left end. What is her position from the right end?", ["28th", "30th", "29th", "27th"], 2, "Position from right = total − position from left + 1 = 40 − 12 + 1 = 29. Forgetting to add 1 gives the wrong answer 28th."], ["English Language", "Select the one word for: 'A place where birds are kept'.", ["Apiary", "Aquarium", "Kennel", "Aviary"], 3, "An aviary is an enclosure for birds. An apiary is a place where bees are kept, an aquarium is for fish and a kennel is for dogs."]]};
